from scipy.optimize import curve_fit
def fitP(f,p0):
    try:
        p,_=curve_fit(lambda x,*q: f(x,*q), P, dP_dt, p0=p0, maxfev=50000)
        return p, np.mean((f(P,*p)-dP_dt)**2)/np.var(dP_dt)
    except Exception as e: return str(e)[:50]
